entries[64051] = { ["name"] = "Rituale des Neumonds", ["text"] = "Wirken in 3 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament (10), Meerestinte (5), Äonenschatten (3)\nOptionale Reagenzien:\n[] (#49)\nBeute von:\nNordend\n\nRituale des Neumonds\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+6 Intelligenz\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nBenutzen: Verwandelt Euch in einen riesigen Wolf. (10 Min Abklingzeit)\n27" }
