entries[64053] = { ["name"] = "Zwielichtfoliant", ["text"] = "Wirken in 3 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament (10), Meerestinte (5), Äonenleben (2)\nOptionale Reagenzien:\n[] (#49)\nBerufsausbilder:\nInschriftenkunde von Nordend (1)\nKosten:\n10\n\nZwielichtfoliant\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+6 Intelligenz\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\n27\n\"Selbst wenn man diesen klobigen, übergroßen Folianten nur hält, fühlt man sich bereits etwas schwerfällig...\"" }
entries[64054] = { ["name"] = "Muschelette Magnifique", ["text"] = "Wirken in 2 sek.\nReagenzien:\nScharfes Muschelfleisch\nQuest:\nMuschelette Surprise\nZone:\nTanaris\n\nQuest:\nMuschelette Surprise\nZone:\nTanaris\n\nWird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 30 Sek. ( 245 * 30 / 5) Gesundheit und ( 225 / 5 * 30) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 385 Angriffskraft und 385 Intelligenz.\n15" }
